<?php
require __DIR__.'/../api/life/store.php';require __DIR__.'/../api/life/ai.php';
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$db->exec(file_get_contents(__DIR__.'/../api/life/schema.sql'));$store=new LifeStore($db);$store->initialize('disposable-history-test');$n=0;function hist($ok){global $n;if(!$ok)throw new Exception('History check '.$n.' failed');$n++;}
$r=$store->read();$list=$r['state']['lists'][0]['id'];$blocked=array_values(array_filter($r['state']['lists'],fn($l)=>$l['name']==='Blocked'))[0]['id'];hist($store->history->page()['entries']===[]);
$r=$store->mutate($r['version'],'task.save',['title'=>'Write first draft','listId'=>$list]);$id=$r['state']['tasks'][0]['id'];hist(count($store->history->page()['entries'])===0);
$r=$store->mutate($r['version'],'task.move',['id'=>$id,'listId'=>$blocked]);hist(count($store->history->page()['entries'])===1);hist($store->history->page()['entries'][0]['status']==='blocked');
$r=$store->mutate($r['version'],'task.save',array_replace($r['state']['tasks'][0],['title'=>'Write final draft']));hist(count($store->history->page()['entries'])===1);hist($store->history->page()['entries'][0]['task']['title']==='Write first draft');
$r=$store->mutate($r['version'],'task.complete',['id'=>$id,'done'=>true]);hist(count($store->history->page(['status'=>'done'])['entries'])===1);$r=$store->mutate($r['version'],'task.complete',['id'=>$id,'done'=>false]);hist(count($store->history->page(['status'=>'done'])['entries'])===1);
$r=$store->mutate($r['version'],'task.archive',['id'=>$id]);hist(count($store->history->page(['status'=>'archived'])['entries'])===1);$saved=$store->history->export();$r=$store->mutate($r['version'],'task.restore',['id'=>$id,'listId'=>$list]);hist($store->history->export()===$saved);
try{$store->mutate($r['version'],'history.delete',['id'=>$saved[0]['id']]);hist(false);}catch(LifeError $e){hist($e->status===400);}hist($store->history->export()===$saved);
// Rollbacks include journal writes; Undo preserves earlier immutable events.
$ai=new LifeAI($store,[],fn()=>[]);$text='Move Write final draft to Blocked';$plan=['authorization'=>$text,'actions'=>[['operation'=>'task.move','arguments'=>json_encode(['id'=>$id,'listId'=>$blocked])],['operation'=>'task.move','arguments'=>json_encode(['id'=>'missing','listId'=>$blocked])]]];try{LifeCommands::execute($store,$ai,$ai->read()['version'],$r['version'],$text,$plan,'history-rollback');hist(false);}catch(LifeError $e){hist($store->history->export()===$saved);}
$plan['actions']=[$plan['actions'][0]];$result=LifeCommands::execute($store,$ai,$ai->read()['version'],$store->read()['version'],$text,$plan,'history-undo');$events=$store->history->export();LifeCommands::undo($store,$ai,$result['version'],$result['receipt']['id']);hist($store->history->export()===$events);
// Account journals are isolated even if the mutable planner is replaced.
$state=$store->read()['state'];$db->prepare('INSERT INTO life_board (id,version,state,updated_at) VALUES (2,1,?,?)')->execute([json_encode($state),LifeStore::now()]);$other=new LifeStore($db,2);$other->history->page();hist(count($other->history->export())===0);$db->prepare('UPDATE life_board SET state=? WHERE id=1')->execute([json_encode(array_replace($state,['tasks'=>[]]))]);hist($store->history->export()===$events);
// More than one page remains available; nothing is trimmed at the 100-entry UI boundary.
for($i=0;$i<101;$i++)$store->mutate($store->read()['version'],'task.save',['title'=>'Blocked history '.$i,'listId'=>$blocked]);$page=$store->history->page();hist(count($page['entries'])===100);hist($page['nextOffset']===100);$second=$store->history->page(['offset'=>100]);hist(count($second['entries'])>0);hist($second['nextOffset']===null);hist(count(array_intersect(array_column($page['entries'],'id'),array_column($second['entries'],'id')))===0);hist(count($store->history->export())===count($events)+101);
echo "$n permanent task history checks passed\n";
